cypress_script:
describe('Opening Links in New Windows', () => {
  it('should open Elemental Selenium in a new window', () => {
    cy.visit('https://the-internet.herokuapp.com/windows');
    cy.get('a').contains('Click Here').click();
    cy.url().should('include', 'http://elementalselenium.com/');
    cy.window().then(win => {
      expect(win.location.href).to.equal('http://elementalselenium.com/');
    });
    cy.go('back');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/windows');
    cy.get('h1').should('contain', 'Opening a new window');
  });
  it('should not change the URL without clicking', () => {
    cy.visit('https://the-internet.herokuapp.com/windows');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/windows');
    cy.get('a').contains('Click Here').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Opening Links in New Windows', () => {
  test('should open Elemental Selenium in a new window', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/windows');
    const [newPage] = await Promise.all([
      page.context().waitForEvent('page'),
      page.click('a:text("Click Here")')
    ]);
    await expect(newPage).toHaveURL('http://elementalselenium.com/');
    await newPage.close();
    await page.waitForTimeout(1000);
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/windows');
    await expect(page.locator('h1')).toContainText('Opening a new window');
  });
  test('should not change the URL without clicking', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/windows');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/windows');
    await expect(page.locator('a:text("Click Here")')).toBeVisible();
  });
});
